use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut total_time = 0;
    for line in input.as_array() {
        let (arrival, duration) = line.as_array().unwrap();
        total_time += arrival * duration;
    }
    serde_json::Value::Number(total_time as f64)
}
